const body = $input.first().json || {};
const telegram = body.message || body.edited_message || {};
const text = (telegram.text || body.text || '').trim();
const chatId = telegram.chat?.id || body.chat_id || null;
const userId = telegram.from?.id || body.user_id || null;
const username = telegram.from?.username || body.username || '';
const intent = body.intent || 'capture_note';
const projectKey = body.project_key || 'personal_os';
const now = new Date();
const iso = now.toISOString();
const ymd = iso.slice(0, 10);
const hhmmss = iso.slice(11, 19).replace(/:/g, '-');
return [{
  json: {
    project_key: projectKey,
    intent,
    source_channel: 'telegram',
    chat_id: chatId,
    user_id: userId,
    username,
    text,
    captured_at: iso,
    note_date: ymd,
    note_time: hhmmss
  }
}];

const allowedIntents = new Set(['agenda', 'reminder', 'study_plan', 'capture_note', 'task', 'weekly_review']);
const row = $input.first().json;
const errors = [];
if (!row.project_key) errors.push('Missing project_key');
if (row.project_key !== 'personal_os') errors.push('Invalid project_key for PERSONAL_OS workflow');
if (!allowedIntents.has(row.intent)) errors.push('Intent not allowed for personal_os');
if (!row.text) errors.push('Empty text payload');
const targetPath = 'PERSONAL_OS/00_INBOX';
if (!targetPath.startsWith('PERSONAL_OS/')) errors.push('Invalid target path');
const isValid = errors.length === 0;
return [{ json: { ...row, is_valid: isValid, errors, target_path: targetPath } }];

const row = $input.first().json;
const safeUser = row.username ? row.username.replace(/[^a-zA-Z0-9_-]/g, '_') : 'unknown';
const fileName = `${row.note_date}_${row.note_time}_${safeUser}.md`;
const note = `# Captura rápida\n\n- project_key: ${row.project_key}\n- intent: ${row.intent}\n- source_channel: ${row.source_channel}\n- user_id: ${row.user_id ?? ''}\n- username: ${row.username || ''}\n- captured_at: ${row.captured_at}\n\n## Contenido\n${row.text}\n`;
const data = Buffer.from(note, 'utf8').toString('base64');
return [{
  json: {
    ...row,
    file_name: fileName,
    file_path: `${row.target_path}/${fileName}`
  },
  binary: {
    data: {
      data,
      fileName,
      mimeType: 'text/markdown'
    }
  }
}];
